+            if (attr == null) {
+                return null;
+            }
+
+            try {
+                return JSON.parseObject(attr, new TypeReference<Set<SubscriptionData>>() {
+                });
+            } catch (Exception e) {
+                log.error("convert remoting extend attribute to subscriptionDataSet failed. data:{}", attr, e);
